'use strict';

// Emoji picker: the #emoji-picker-sheet overlay (bottom sheet on phones,
// centered dialog from `sm` up) with keyword search, category tabs, recents
// and a skin-tone choice. Opened from the new/edit list modal's "Choisir un
// émoji" button (app.js); anything else can call
// window.TrakkaEmojiPicker.open({ onSelect, returnFocus }).
//
// No dependency and nothing to build: the data is static/emoji/{fr,en}.json
// (generated by tools/genemoji from emojibase-data, i.e. Unicode CLDR
// labels/keywords — see that file for the entry format), precached by sw.js
// so the picker works offline. It's only fetched on first open, in the
// current UI language, and its ~1,900 buttons are built once per language
// and reused. Emojis newer than what the device's font can draw are left
// out (see detectSupport), so nobody picks an icon that renders as a box.
//
// DOM is built with createElement/textContent only, like the rest of the
// frontend. Recents and the skin tone are per-browser conveniences kept in
// localStorage; both degrade to "not remembered" when storage is blocked.
(function () {
  const RECENTS_KEY = 'trakka:emoji-recents';
  const TONE_KEY = 'trakka:emoji-tone';
  const MAX_RECENTS = 24;
  const MAX_RESULTS = 240;
  const SKIN_TONES = ['', '\u{1F3FB}', '\u{1F3FC}', '\u{1F3FD}', '\u{1F3FE}', '\u{1F3FF}'];
  const TONE_OR_VS16 = /[\u{1F3FB}-\u{1F3FF}️]/gu;
  // Must match base.css's .emoji-picker-cell font stack, so the support
  // probe measures the same font the grid will render with.
  const EMOJI_FONT = '"Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol","Noto Color Emoji","Twemoji Mozilla","Android Emoji",sans-serif';
  // Newest first: one emoji per Emoji version that only a font covering
  // that version draws as a single color glyph (13.1 and 15.1 only added
  // ZWJ sequences, hence the sequences there).
  const VERSION_PROBES = [
    [17, '\u{1FAEA}'],
    [16, '\u{1FAE9}'],
    [15.1, '\u{1F642}‍↔️'],
    [15, '\u{1FAE8}'],
    [14, '\u{1FAE0}'],
    [13.1, '\u{1F636}‍\u{1F32B}️'],
    [13, '\u{1F972}'],
  ];

  const els = {
    sheet: document.getElementById('emoji-picker-sheet'),
    panel: document.getElementById('emoji-picker-panel'),
    closeButton: document.getElementById('emoji-picker-close-button'),
    search: document.getElementById('emoji-picker-search'),
    toneButton: document.getElementById('emoji-picker-tone-button'),
    toneRow: document.getElementById('emoji-picker-tones'),
    toneOptions: document.querySelectorAll('#emoji-picker-tones [data-emoji-tone]'),
    tabs: document.querySelectorAll('#emoji-picker-categories [data-emoji-category]'),
    scroller: document.getElementById('emoji-picker-scroller'),
    status: document.getElementById('emoji-picker-status'),
    results: document.getElementById('emoji-picker-results'),
    resultsGrid: document.getElementById('emoji-picker-results-grid'),
    sections: document.getElementById('emoji-picker-sections'),
  };
  if (!els.sheet) return;

  const t = (key, vars) => window.TrakkaI18n.t(key, vars);

  // { lang, entries, byKey } once loaded — entries in display order, each
  // { emoji, label, tone, labelWords, keywordWords }; byKey maps an emoji
  // stripped of skin tones/VS16 back to its entry (labels for recents).
  let data = null;
  let loading = null;
  let builtLang = null;
  let tonedCells = [];
  let recentSection = null;
  let onSelect = null;
  let returnFocus = null;
  let addedScrollLock = false;
  let scrollSpyFrame = 0;
  let tone = readTone();

  // -------------------------------------------------------------------------
  // Storage (per-browser conveniences only)
  // -------------------------------------------------------------------------

  function readStored(key) {
    try {
      return JSON.parse(localStorage.getItem(key));
    } catch {
      return null;
    }
  }

  function writeStored(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      // Storage blocked or full: the choice just isn't remembered.
    }
  }

  function readTone() {
    const value = readStored(TONE_KEY);
    return Number.isInteger(value) && value >= 0 && value < SKIN_TONES.length ? value : 0;
  }

  function readRecents() {
    const value = readStored(RECENTS_KEY);
    return Array.isArray(value) ? value.filter((e) => typeof e === 'string' && e).slice(0, MAX_RECENTS) : [];
  }

  function rememberRecent(emoji) {
    const recents = readRecents().filter((e) => e !== emoji);
    recents.unshift(emoji);
    writeStored(RECENTS_KEY, recents.slice(0, MAX_RECENTS));
  }

  // -------------------------------------------------------------------------
  // Text helpers
  // -------------------------------------------------------------------------

  // Case-, accent- and ligature-insensitive words, so "coeur" finds "cœur"
  // and "cafe" finds "café"; apostrophes split words ("d’accord" → "d",
  // "accord") on both the data and the query side.
  function words(text) {
    return text
      .toLowerCase()
      .normalize('NFD')
      .replace(/\p{M}/gu, '')
      .replace(/œ/g, 'oe')
      .replace(/æ/g, 'ae')
      .split(/[^\p{L}\p{N}]+/u)
      .filter(Boolean);
  }

  // Mirrors applyTone in tools/genemoji/main.go, which only emits a rule
  // after checking it reproduces every real variant: 1 = modifier after the
  // first code point, 2 = after the first and the last; a VS16 right after
  // an insertion point is dropped (👍️ → 👍🏽).
  function applyTone(emoji, rule, modifier) {
    if (!rule || !modifier) return emoji;
    const cps = Array.from(emoji);
    const last = cps.length - 1;
    let out = '';
    for (let i = 0; i < cps.length; i++) {
      out += cps[i];
      if (i === 0 || (rule === 2 && i === last)) {
        out += modifier;
        if (cps[i + 1] === '️') i++;
      }
    }
    return out;
  }

  // -------------------------------------------------------------------------
  // Font support detection
  // -------------------------------------------------------------------------

  // Draws `text` scaled down to a single pixel in two fill colors: a color
  // emoji glyph ignores fillStyle and averages to the same non-empty pixel
  // both times, while a missing-glyph box or a monochrome fallback follows
  // the fill color. An unsupported ZWJ sequence falls back to several
  // color glyphs side by side, which the width check catches.
  function makeProbe() {
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 1;
      canvas.height = 1;
      const ctx = canvas.getContext('2d', { willReadFrequently: true });
      if (!ctx) return null;
      ctx.textBaseline = 'top';
      ctx.font = `100px ${EMOJI_FONT}`;
      const pixel = (text, color) => {
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.clearRect(0, 0, 1, 1);
        ctx.scale(0.01, 0.01);
        ctx.fillStyle = color;
        ctx.fillText(text, 0, 0);
        return ctx.getImageData(0, 0, 1, 1).data.join(',');
      };
      const baseWidth = ctx.measureText('\u{1F600}').width;
      return (text) => {
        const dark = pixel(text, '#000');
        if (dark !== pixel(text, '#fff') || dark.startsWith('0,0,0,')) return false;
        if (!text.includes('‍')) return true;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        return ctx.measureText(text).width < baseWidth * 1.5;
      };
    } catch {
      return null;
    }
  }

  // When the canvas can't be read (blocked, or randomized by anti-
  // fingerprinting so even 😀 fails), nothing is filtered — better an
  // occasional box than hiding every emoji newer than 2019.
  function detectSupport() {
    const supported = makeProbe();
    if (!supported || !supported('\u{1F600}')) return { maxVersion: Infinity, flags: true };
    const probe = VERSION_PROBES.find(([, emoji]) => supported(emoji));
    // Windows' emoji font has no flags: they'd show as bare letter pairs.
    return { maxVersion: probe ? probe[0] : 12.1, flags: supported('\u{1F1EB}\u{1F1F7}') };
  }

  // -------------------------------------------------------------------------
  // Data
  // -------------------------------------------------------------------------

  function load(lang) {
    if (data && data.lang === lang) return Promise.resolve(data);
    if (loading && loading.lang === lang) return loading.promise;
    const promise = fetch(`/emoji/${lang}.json`)
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then((json) => {
        data = prepare(lang, json);
        return data;
      })
      .finally(() => {
        if (loading && loading.promise === promise) loading = null;
      });
    loading = { lang, promise };
    return promise;
  }

  function prepare(lang, json) {
    const support = detectSupport();
    const entries = [];
    const byKey = new Map();
    const groups = [];
    for (const group of json.groups || []) {
      if (group.id === 'flags' && !support.flags) continue;
      const groupEntries = [];
      for (const [emoji, label, keywords = '', toneRule = 0, version = 0] of group.e || []) {
        if (version > support.maxVersion) continue;
        const entry = {
          emoji,
          label,
          tone: toneRule,
          labelWords: words(label),
          keywordWords: words(keywords),
        };
        groupEntries.push(entry);
        entries.push(entry);
        const key = emoji.replace(TONE_OR_VS16, '');
        if (!byKey.has(key)) byKey.set(key, entry);
      }
      if (groupEntries.length) groups.push({ id: group.id, entries: groupEntries });
    }
    return { lang, entries, byKey, groups };
  }

  // -------------------------------------------------------------------------
  // Rendering
  // -------------------------------------------------------------------------

  function buildCell(emoji, label) {
    const button = document.createElement('button');
    button.type = 'button';
    button.className = 'emoji-picker-cell';
    button.tabIndex = -1;
    button.textContent = emoji;
    button.dataset.emoji = emoji;
    button.title = label;
    button.setAttribute('aria-label', label);
    return button;
  }

  function buildEntryCell(entry) {
    const cell = buildCell(applyTone(entry.emoji, entry.tone, SKIN_TONES[tone]), entry.label);
    if (entry.tone) tonedCells.push({ cell, entry });
    return cell;
  }

  function buildSection(id, headingText) {
    const section = document.createElement('section');
    section.dataset.category = id;
    const heading = document.createElement('h3');
    heading.id = `emoji-picker-heading-${id}`;
    heading.className = 'sticky top-0 z-10 bg-slate-100 dark:bg-slate-800 px-1 pb-1 pt-3 text-xs font-semibold text-slate-500 dark:text-slate-400';
    heading.textContent = headingText;
    const grid = document.createElement('div');
    grid.className = 'emoji-picker-grid';
    grid.setAttribute('role', 'group');
    grid.setAttribute('aria-labelledby', heading.id);
    section.append(heading, grid);
    return { section, grid };
  }

  function buildSections() {
    tonedCells = [];
    const fragment = document.createDocumentFragment();
    const recent = buildSection('recent', t('emojiPicker.categories.recent'));
    recentSection = recent.section;
    fragment.append(recentSection);
    for (const group of data.groups) {
      const { section, grid } = buildSection(group.id, t(`emojiPicker.categories.${group.id}`));
      for (const entry of group.entries) grid.append(buildEntryCell(entry));
      fragment.append(section);
    }
    els.sections.replaceChildren(fragment);
    builtLang = data.lang;
    const available = new Set(data.groups.map((group) => group.id));
    for (const tab of els.tabs) {
      if (tab.dataset.emojiCategory !== 'recent') tab.hidden = !available.has(tab.dataset.emojiCategory);
    }
  }

  function renderRecents() {
    const grid = recentSection.querySelector('.emoji-picker-grid');
    const recents = readRecents();
    grid.replaceChildren(...recents.map((emoji) => {
      const entry = data.byKey.get(emoji.replace(TONE_OR_VS16, ''));
      return buildCell(emoji, entry ? entry.label : emoji);
    }));
    recentSection.hidden = recents.length === 0;
    for (const tab of els.tabs) {
      if (tab.dataset.emojiCategory === 'recent') tab.hidden = recents.length === 0;
    }
  }

  // True once the grid on screen was built from the loaded data (false
  // while loading, after a failed load, or after a language switch).
  function isReady() {
    return data !== null && builtLang === data.lang;
  }

  function setStatus(text) {
    els.status.textContent = text || '';
    els.status.hidden = !text;
  }

  // Word-prefix search over the current language's label and CLDR
  // keywords; every query word must match. A hit on the label ranks above
  // a keyword-only hit, an exact label word above a prefix, and among equal
  // hits the shorter label wins ("coeur" → ❤️ "cœur rouge" before 😍
  // "visage souriant avec yeux en forme de cœur").
  function renderSearch() {
    if (!isReady()) return;
    const query = els.search.value.trim();
    const tokens = words(query);
    const searching = tokens.length > 0;
    els.sections.hidden = searching;
    els.results.hidden = !searching;
    if (!searching) {
      setStatus('');
      updateActiveTab();
      return;
    }
    const hits = [];
    for (const entry of data.entries) {
      let score = 0;
      for (const token of tokens) {
        if (entry.labelWords.includes(token)) score += 3;
        else if (entry.labelWords.some((word) => word.startsWith(token))) score += 2;
        else if (entry.keywordWords.some((word) => word.startsWith(token))) score += 1;
        else {
          score = 0;
          break;
        }
      }
      if (score > 0) hits.push({ entry, score });
    }
    hits.sort((a, b) => b.score - a.score || a.entry.labelWords.length - b.entry.labelWords.length);
    els.resultsGrid.replaceChildren(...hits.slice(0, MAX_RESULTS).map(({ entry }) =>
      buildCell(applyTone(entry.emoji, entry.tone, SKIN_TONES[tone]), entry.label)));
    setStatus(hits.length ? '' : t('emojiPicker.noResults', { query }));
    els.scroller.scrollTop = 0;
    updateActiveTab();
  }

  // -------------------------------------------------------------------------
  // Category tabs & scroll spy
  // -------------------------------------------------------------------------

  function visibleSections() {
    return [...els.sections.children].filter((section) => !section.hidden);
  }

  function updateActiveTab() {
    let active = null;
    if (!els.sections.hidden && isReady()) {
      const top = els.scroller.scrollTop + 8;
      for (const section of visibleSections()) {
        if (section.offsetTop <= top) active = section.dataset.category;
      }
    }
    for (const tab of els.tabs) {
      const isActive = tab.dataset.emojiCategory === active;
      tab.classList.toggle('border-sky-500', isActive);
      tab.classList.toggle('border-transparent', !isActive);
      tab.classList.toggle('opacity-50', !isActive);
      if (isActive) tab.setAttribute('aria-current', 'true');
      else tab.removeAttribute('aria-current');
    }
  }

  function scrollToCategory(id) {
    if (!isReady()) return;
    if (els.search.value) {
      els.search.value = '';
      renderSearch();
    }
    const section = visibleSections().find((s) => s.dataset.category === id);
    if (!section) return;
    els.scroller.scrollTop = section.offsetTop;
    updateActiveTab();
  }

  // -------------------------------------------------------------------------
  // Skin tone
  // -------------------------------------------------------------------------

  function renderTone() {
    els.toneButton.textContent = `✋${SKIN_TONES[tone]}`;
    for (const option of els.toneOptions) {
      option.setAttribute('aria-pressed', String(Number(option.dataset.emojiTone) === tone));
    }
  }

  function setTone(value) {
    tone = value;
    writeStored(TONE_KEY, tone);
    renderTone();
    for (const { cell, entry } of tonedCells) {
      const emoji = applyTone(entry.emoji, entry.tone, SKIN_TONES[tone]);
      cell.textContent = emoji;
      cell.dataset.emoji = emoji;
    }
    if (els.search.value.trim()) renderSearch();
  }

  function setToneRowOpen(open) {
    els.toneRow.hidden = !open;
    els.toneButton.setAttribute('aria-expanded', String(open));
  }

  // -------------------------------------------------------------------------
  // Keyboard navigation: the grids are one tab stop (roving tabindex), and
  // the arrow keys move between cells, across sections too.
  // -------------------------------------------------------------------------

  function activeGrids() {
    const scope = els.results.hidden ? visibleSections() : [els.results];
    return scope.map((node) => node.querySelector('.emoji-picker-grid')).filter((grid) => grid && grid.children.length);
  }

  function columnCount(grid) {
    const cells = grid.children;
    const top = cells[0].offsetTop;
    let count = 0;
    while (count < cells.length && cells[count].offsetTop === top) count++;
    return Math.max(1, count);
  }

  function focusCell(cell) {
    if (!cell) return;
    for (const other of els.scroller.querySelectorAll('.emoji-picker-cell[tabindex="0"]')) other.tabIndex = -1;
    cell.tabIndex = 0;
    cell.focus();
    // Keep the focused row clear of the sticky section heading.
    const heading = cell.closest('section')?.querySelector('h3');
    const headingHeight = heading ? heading.offsetHeight : 0;
    const cellTop = cell.offsetTop - els.scroller.scrollTop;
    if (cellTop < headingHeight) els.scroller.scrollTop = cell.offsetTop - headingHeight;
  }

  function neighborCell(cell, key) {
    const grid = cell.parentElement;
    const cells = [...grid.children];
    const index = cells.indexOf(cell);
    const cols = columnCount(grid);
    const grids = activeGrids();
    const gridIndex = grids.indexOf(grid);
    const nextGrid = grids[gridIndex + 1];
    const prevGrid = grids[gridIndex - 1];
    switch (key) {
      case 'ArrowRight':
        return cells[index + 1] || nextGrid?.firstElementChild;
      case 'ArrowLeft':
        return cells[index - 1] || prevGrid?.lastElementChild;
      case 'ArrowDown': {
        if (index + cols < cells.length) return cells[index + cols];
        if (Math.floor(index / cols) < Math.floor((cells.length - 1) / cols)) return cells[cells.length - 1];
        if (!nextGrid) return null;
        return nextGrid.children[Math.min(index % cols, nextGrid.children.length - 1)];
      }
      case 'ArrowUp': {
        if (index - cols >= 0) return cells[index - cols];
        if (!prevGrid) return null;
        const prevCells = prevGrid.children;
        const prevCols = columnCount(prevGrid);
        const lastRowStart = Math.floor((prevCells.length - 1) / prevCols) * prevCols;
        return prevCells[Math.min(lastRowStart + (index % cols), prevCells.length - 1)];
      }
      case 'Home':
        return grids[0]?.firstElementChild;
      case 'End':
        return grids[grids.length - 1]?.lastElementChild;
      default:
        return undefined;
    }
  }

  // -------------------------------------------------------------------------
  // Open / close / select
  // -------------------------------------------------------------------------

  function isOpen() {
    return !els.sheet.hidden;
  }

  async function open(options = {}) {
    if (isOpen()) return;
    onSelect = typeof options.onSelect === 'function' ? options.onSelect : null;
    returnFocus = options.returnFocus || document.activeElement;
    els.search.value = '';
    setToneRowOpen(false);
    renderTone();
    els.results.hidden = true;
    els.sections.hidden = false;
    els.sheet.hidden = false;
    addedScrollLock = !TrakkaScrollLock.isLocked();
    if (addedScrollLock) TrakkaScrollLock.lock();
    // A fine pointer means a physical keyboard is likely: start in the
    // search field. On touch, focusing it would pop the on-screen keyboard
    // over half of the grid, so the dialog itself takes focus instead.
    if (window.matchMedia('(hover: hover) and (pointer: fine)').matches) els.search.focus();
    else els.panel.focus({ preventScroll: true });

    const lang = window.TrakkaI18n.getLang();
    if (builtLang !== lang) {
      els.sections.replaceChildren();
      setStatus(t('emojiPicker.loading'));
      try {
        await load(lang);
      } catch {
        if (isOpen()) setStatus(t('emojiPicker.loadError'));
        return;
      }
      if (builtLang !== data.lang) buildSections();
      setStatus('');
    }
    if (!isOpen()) return;
    renderRecents();
    els.scroller.scrollTop = 0;
    const firstCell = els.sections.querySelector('section:not([hidden]) .emoji-picker-cell');
    for (const cell of els.scroller.querySelectorAll('.emoji-picker-cell[tabindex="0"]')) cell.tabIndex = -1;
    if (firstCell) firstCell.tabIndex = 0;
    if (els.search.value.trim()) renderSearch();
    else updateActiveTab();
  }

  function close() {
    if (!isOpen()) return;
    els.sheet.hidden = true;
    if (addedScrollLock) TrakkaScrollLock.unlock();
    addedScrollLock = false;
    onSelect = null;
    if (returnFocus && typeof returnFocus.focus === 'function') returnFocus.focus();
    returnFocus = null;
  }

  function choose(emoji) {
    const callback = onSelect;
    rememberRecent(emoji);
    close();
    if (callback) callback(emoji);
  }

  // -------------------------------------------------------------------------
  // Wiring
  // -------------------------------------------------------------------------

  els.closeButton.addEventListener('click', close);
  els.sheet.addEventListener('click', (event) => {
    if (event.target === els.sheet) close();
  });

  els.scroller.addEventListener('click', (event) => {
    const cell = event.target.closest('.emoji-picker-cell');
    if (cell) choose(cell.dataset.emoji);
  });

  els.scroller.addEventListener('keydown', (event) => {
    const cell = event.target.closest('.emoji-picker-cell');
    if (!cell) return;
    const target = neighborCell(cell, event.key);
    if (target === undefined) return;
    event.preventDefault();
    focusCell(target);
  });

  els.scroller.addEventListener('focusin', (event) => {
    const cell = event.target.closest('.emoji-picker-cell');
    if (!cell || cell.tabIndex === 0) return;
    for (const other of els.scroller.querySelectorAll('.emoji-picker-cell[tabindex="0"]')) other.tabIndex = -1;
    cell.tabIndex = 0;
  });

  els.scroller.addEventListener('scroll', () => {
    if (scrollSpyFrame) return;
    scrollSpyFrame = requestAnimationFrame(() => {
      scrollSpyFrame = 0;
      updateActiveTab();
    });
  }, { passive: true });

  els.search.addEventListener('input', renderSearch);

  els.search.addEventListener('keydown', (event) => {
    if (event.key === 'Enter') {
      event.preventDefault();
      const first = els.results.hidden ? null : els.resultsGrid.firstElementChild;
      if (first) choose(first.dataset.emoji);
    } else if (event.key === 'ArrowDown') {
      const grid = activeGrids()[0];
      if (!grid) return;
      event.preventDefault();
      focusCell(grid.firstElementChild);
    }
  });

  for (const tab of els.tabs) {
    tab.addEventListener('click', () => scrollToCategory(tab.dataset.emojiCategory));
  }

  els.toneButton.addEventListener('click', () => setToneRowOpen(els.toneRow.hidden));
  for (const option of els.toneOptions) {
    option.addEventListener('click', () => {
      setTone(Number(option.dataset.emojiTone));
      setToneRowOpen(false);
      els.toneButton.focus();
    });
  }

  // Capture phase on window, ahead of every document-level Escape handler:
  // an Escape meant for the picker must not also close the list modal
  // underneath it (app.js) or leave selection mode (selection.js). The
  // first Escape clears a non-empty search, the next one closes.
  window.addEventListener('keydown', (event) => {
    if (event.key !== 'Escape' || !isOpen()) return;
    event.preventDefault();
    event.stopPropagation();
    if (!els.toneRow.hidden) {
      setToneRowOpen(false);
      els.toneButton.focus();
    } else if (els.search.value) {
      els.search.value = '';
      renderSearch();
    } else {
      close();
    }
  }, true);

  // The data (labels, keywords) is per language: rebuild on next open.
  document.addEventListener('trakka:lang-changed', () => {
    builtLang = null;
  });

  window.TrakkaEmojiPicker = { open, close, isOpen };
})();
